#!/usr/bin/env node
import { spawnSync } from 'node:child_process';
import { readdirSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..', '..');

function discover(dir, out) {
  for (const entry of readdirSync(dir)) {
    if (entry === 'node_modules' || entry === '.git') continue;
    const full = path.join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) {
      discover(full, out);
    } else if (entry.endsWith('.test.ts')) {
      out.push(full);
    }
  }
  return out;
}

const argPath = process.argv[2];
let targets;

if (argPath) {
  const resolved = path.resolve(repoRoot, argPath);
  const st = statSync(resolved);
  targets = st.isDirectory() ? discover(resolved, []) : [resolved];
} else {
  targets = discover(path.join(repoRoot, '_local'), []);
}

if (targets.length === 0) {
  console.log('No *.test.ts files found.');
  process.exit(0);
}

const result = spawnSync(
  process.execPath,
  ['--test', '--test-reporter=spec', '--no-warnings=MODULE_TYPELESS_PACKAGE_JSON', ...targets],
  { cwd: repoRoot, stdio: 'inherit' }
);

process.exit(result.status ?? 1);

